export type FsBytes = {
	/**  정규화한 실제 경로. */
	path: string,
	/**  파일 전체 크기. */
	size: number,
	mtimeMs: number | null,
	/**  읽은 범위의 시작(요청한 `offset`). */
	offset: number,
	/**  읽은 바이트, 표준 base64. 파일 끝을 넘는 부분은 없다. */
	data: string,
	/**  읽은 범위가 파일 끝까지 닿았다. */
	eof: boolean,
};

/**  읽거나 쓸 내용. */
export type FsContent = 
/**
 *  UTF-8 텍스트. 읽기에서는 파일 앞의 BOM 을 뺀 것이다(`judgment.bom` 이 알린다). 판정의 인코딩이 UTF-8 이 아니면(UTF-16 ·
 *  짐작한 인코딩) 그 인코딩에서 풀어 낸 것이고 `judgment.editable` 이 거짓이다 — 그 텍스트를 `fs.write` 로 되돌려 쓰면 원래 바이트가
 *  바뀐다(결정 M1-D12).
 */
{ kind: "text"; text: string } | 
/**  바이트 그대로(BOM 포함), 표준 base64. */
{ kind: "base64"; data: string };

export type FsCopied = {
	/**  만든 복사본의 경로. */
	to: string,
	/**  복사한 파일 · 폴더 · 심링크 수(맨 위 항목 포함). */
	files: number,
	dirs: number,
	links: number,
	/**  건너뛴 항목(특수 파일, Windows 의 심링크)의 원본 경로. */
	skipped: string[],
};

/**  만들 것. */
export type FsCreateKind = "file" | "dir";

export type FsCreateParams = {
	projectId: string,
	worktree?: string | null,
	/**  만들 절대 경로. 들어갈 폴더는 있어야 한다. */
	path: string,
	kind: FsCreateKind,
};

export type FsCreated = {
	/**  만든 경로(들어간 폴더를 실제 경로로 푼 것). */
	path: string,
};

/**  폴더의 항목 하나. */
export type FsEntry = {
	/**  UTF-8 이 아닌 이름은 대체 문자로 바뀌어 온다. */
	name: string,
	kind: EntryKind,
	/**  심링크면 가리키는 것의 종류. 깨진 링크 · 루트 밖을 가리키는 링크 · 심링크가 아니면 `null`. */
	target: EntryKind | null,
	/**  심링크의 실제 대상이 프로젝트 루트 밖이다. 따라 읽거나 펼칠 수 없다(`fs.*` 가 거절한다). */
	outside: boolean,
	/**  바이트. 심링크면 대상의 크기(깨졌거나 루트 밖이면 0). */
	size: number,
	/**  수정 시각(유닉스 밀리초). 심링크면 대상의 것(루트 밖이면 링크 자신의 것). 알 수 없으면 `null`. */
	mtimeMs: number | null,
	/**  `.gitignore` 등으로 무시되는 항목(무시된 폴더 안의 항목 포함). */
	ignored: boolean,
};

/**  원본 · 대상을 받는 요청(`fs.rename` · `fs.copy`). */
export type FsFromToParams = {
	projectId: string,
	worktree?: string | null,
	/**  옮기거나 복사할 항목의 절대 경로. 심링크면 링크 자체다. */
	from: string,
	/**  새 절대 경로(폴더 안의 이름까지). 들어갈 폴더는 있어야 하고 이 이름은 없어야 한다. */
	to: string,
};

export type FsList = {
	/**  정규화한 실제 경로. */
	path: string,
	/**  이름순. */
	entries: FsEntry[],
};

export type FsMoved = {
	/**  옮긴 항목의 원래 경로(들어 있던 폴더를 실제 경로로 푼 것). 열린 문서 · 탭의 키를 이것 아래에서 `to` 아래로 바꾼다. */
	from: string,
	to: string,
};

/**  경로 하나를 받는 요청(`fs.list` · `fs.stat`). */
export type FsPathParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). 그 워크트리 안의 프로젝트 루트도 접근 범위가 된다. */
	worktree?: string | null,
	/**  절대 경로. */
	path: string,
};

export type FsRead = {
	/**  정규화한 실제 경로. */
	path: string,
	/**  파일 전체 크기. */
	size: number,
	mtimeMs: number | null,
	/**  읽은 범위의 시작. */
	offset: number,
	/**  읽은 범위가 파일 끝까지 닿았다. */
	eof: boolean,
	/**  파일 전체를 읽었을 때만 있다. `fs.write` 의 `expectedVersion` 으로 그대로 돌려준다. */
	version: string | null,
	content: FsContent,
	/**  판정. 텍스트/바이너리 · BOM 은 파일 앞부분으로, 인코딩 · 줄바꿈 · 긴 줄은 읽은 범위로 정한다. */
	judgment: Judgment,
};

export type FsReadBytesParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`fs.read` 와 같다). */
	worktree?: string | null,
	/**  절대 경로. */
	path: string,
	/**  시작 바이트. */
	offset: number,
	/**  최대 바이트. 64 KiB 까지. */
	length: number,
};

export type FsReadParams = {
	projectId: string,
	worktree?: string | null,
	/**  절대 경로. */
	path: string,
	/**  범위 읽기의 시작 바이트. `offset` · `length` 가 모두 없으면 파일 전체를 읽는다(50 MiB 까지). */
	offset?: number | null,
	/**  범위 읽기의 최대 바이트(50 MiB 까지). 없으면 끝까지(최대 50 MiB). */
	length?: number | null,
	/**  텍스트여도 바이트(base64)로 받는다(hex 뷰어 · 이미지). */
	bytes?: boolean,
};

export type FsStat = {
	/**  정규화한 실제 경로(심링크를 모두 따라간 것). 문서 모델의 키다. */
	path: string,
	/**  요청 경로 자리의 종류(심링크면 `symlink`). */
	kind: EntryKind,
	/**  심링크면 가리키는 것의 종류. 깨진 링크 · 심링크가 아니면 `null`. */
	target: EntryKind | null,
	/**  바이트(심링크면 대상의 것). */
	size: number,
	mtimeMs: number | null,
	/**  쓰기 권한이 없다(`fs.write` 가 거절한다). */
	readonly: boolean,
	/**  파일이면 크기 등급(결정 M1-D9). 읽지 않고 정하므로 「열지 않음」 판단에 바이트를 읽지 않는다. */
	sizeClass: SizeClass | null,
};

export type FsTrashFailure = {
	path: string,
	reason: FsTrashReason,
	message: string,
};

export type FsTrashParams = {
	projectId: string,
	worktree?: string | null,
	/**  지울 항목의 절대 경로들. 하나라도 루트 밖이면 아무것도 지우지 않고 오류다. 다른 항목 아래의 항목은 그 위 항목과 함께 간다. */
	paths: string[],
	/**  휴지통을 거치지 않고 영구히 지운다. UI 는 휴지통에 넣지 못한 항목(`failed` 의 `unavailable`)을 사람에게 확인한 뒤에만 켠다. */
	permanent?: boolean,
};

/**  지우지 못한 이유. */
export type FsTrashReason = 
/**  이 항목을 넣을 휴지통이 없거나 쓰지 못한다(휴지통이 없는 볼륨 · 환경). 확인 뒤 `permanent` 로 지울 수 있다. */
"unavailable" | 
/**  이 프로세스가 그 항목을 들어 낼 권한이 없다(들어 있는 폴더에 쓰기 권한이 없다). 영구 삭제도 실패한다. */
"permission" | 
/**  그사이 없어졌다. */
"missing" | 
/**  그 밖의 실패(영구 삭제의 IO 오류 등). */
"failed";

export type FsTrashed = {
	/**  휴지통에 넣었거나(`permanent` 면 지웠거나) 한 항목. */
	removed: string[],
	failed: FsTrashFailure[],
};

export type FsWatchParams = {
	projectId: string,
	/**  창의 활성 워크트리 꼭대기(`ActiveWorktree.top`). 있으면 그 워크트리 안의 프로젝트 루트를, 없으면 프로젝트의 등록 루트를 본다. */
	worktree?: string | null,
};

export type FsWatchedRoot = {
	path: string,
	mode: WatchMode,
};

/**  `fs.watch` 의 항목: 지금 보는 루트와 방식. 감시를 다 건 뒤 한 번, 방식이 바뀔 때마다(한도 초과 → 폴링) 한 번. */
export type FsWatching = {
	roots: FsWatchedRoot[],
};

export type FsWriteParams = {
	projectId: string,
	worktree?: string | null,
	/**  절대 경로. 심링크면 대상 파일을 바꾼다(정규화한 실제 경로가 루트 안이어야 한다). 폴더는 있어야 한다. */
	path: string,
	content: FsContent,
	/**  텍스트 앞에 UTF-8 BOM 을 붙인다. 읽을 때 `judgment.bom` 이 `utf8` 이었으면 켠다. `base64` 내용에는 쓸 수 없다. */
	bom?: boolean,
	/**  읽을 때 받은 `version`. 지금 파일과 다르면 쓰지 않고 `CONFLICT`. 없으면 새 파일을 만든다 — 파일이 이미 있으면 `CONFLICT`. */
	expectedVersion?: string | null,
};

export type FsWritten = {
	/**  쓴 실제 경로. */
	path: string,
	size: number,
	mtimeMs: number | null,
	/**  쓴 뒤의 `version`. 다음 쓰기의 `expectedVersion`. */
	version: string,
};

export type HighlightSpan = {
	from: number,
	to: number,
	/**  테마 토큰 이름은 `syntax.<token>` 이다(`docs/design/07-extensibility.md` 「3. 테마」). */
	token: SyntaxToken,
};

export type HostInfo = {
	hostId: string,
	/**  `local`(데스크톱 프로세스 안) 또는 `relay`(원격 데몬). */
	kind: string,
	version: string,
	os: string,
	arch: string,
};

export type I18nResource = {
	locale: string,
	extension: string,
	/**  사람이 읽는 위치(`builtin:i18n-default/i18n/ko/app.ftl` 또는 절대 경로). */
	file: string,
	/**  `.ftl` 파일 내용 그대로. */
	source: string,
};

export type I18nState = {
	/**  설정 값(`"system"` 또는 언어 태그). 설정이 잘못됐으면 `"system"`. */
	setting: string,
	/**  쓸 언어 순서. 첫째가 고른 언어, 끝이 폴백(`en`)이다. */
	locales: string[],
	/**  등록된 언어(등록 순서). 언어 고르기 목록이다. */
	languages: LanguageInfo[],
	/**  `locales` 의 리소스. `locales` 순서, 언어 안에서는 파일 이름순이다. */
	resources: I18nResource[],
};

/**
 *  요청 id. JSON-RPC 2.0 은 숫자 · 문자열 · null 을 허용한다.
 *  숫자는 정수(i64)만 받는다 — 분수 id 는 명세가 비권장하고 비교가 불안정하다.
 *  TS 로는 `number` 다 — id 는 클라이언트가 고르므로 2^53 안에 머문다([`JsNumber`]).
 */
export type Id = number | string | null;

/**  `jsonrpc` 필드. 값은 `"2.0"` 하나다. */
export type JsonRpcVersion = "2.0";

/**
 *  `serde_json::Value` 필드를 TS 로 내보낼 때 쓰는 표식. 값으로 쓰지 않는다.
 * 
 *  필드 타입은 `serde_json::Value` 로 두고 `#[specta(type = pw_rpc::JsonValue)]` 를 단다.
 *  specta 의 `Value` 구현은 숫자를 i64/u64 로 표현해 TS 내보내기가 BigInt 금지로 실패한다.
 */
export type JsonValue = null | boolean | number | string | JsonValue[] | { [key in string]: JsonValue };

/**  읽은 내용의 판정. */
export type Judgment = {
	/**  파일 앞 8 KiB 에 NUL 이 있다(UTF-16 BOM 이 있으면 텍스트로 본다). */
	binary: boolean,
	/**
	 *  읽은 범위의 WHATWG 인코딩 이름(`UTF-8` · `UTF-16LE` · `UTF-16BE` · 짐작한 것). UTF-16 은 BOM 으로, UTF-8 로 읽히지 않는
	 *  텍스트는 `chardetng` 로 짐작한다(예: `EUC-KR` · `Shift_JIS` · `windows-1252`, 결정 M1-D12). 바이너리면 `null`. 거의 UTF-8
	 *  이면(`lossy`) `UTF-8` 이다.
	 */
	encoding: string | null,
	/**
	 *  인코딩이 `UTF-8` 이지만 유효하지 않은 바이트가 있어(쓰는 중인 로그 · 끝이 잘린 파일 등) 그 바이트를 U+FFFD 로 바꿔 풀었다.
	 *  편집하지 않는다 — 저장하면 그 바이트가 U+FFFD 로 바뀐다.
	 */
	lossy: boolean,
	/**  파일 앞의 BOM. */
	bom: Bom | null,
	lineEnding: LineEnding,
	/**  읽은 범위에 1만 자를 넘는 줄이 있다. */
	longLines: boolean,
	/**  파일 전체 크기의 등급. */
	sizeClass: SizeClass,
	/**  에디터로 편집 · 저장할 수 있다: 텍스트, 유효한 UTF-8(BOM 유무 무관, 결정 M1-D12, `lossy` 아님), 5 MiB 이하. */
	editable: boolean,
	/**  구문 강조 · 줄바꿈을 켠다: 텍스트, 5 MiB 이하, 1만 자 넘는 줄 없음(결정 M1-D9). */
	highlight: boolean,
};

export type KeymapContributionKind = 
/**  전체 키맵. 기본 키맵 대신 하나를 고른다. */
"base" | 
/**  베이스 위에 병합하는 일부 바인딩. */
"bindings";

export type KeymapFile = {
	id: string,
	extension: string,
	kind: KeymapContributionKind,
	/**  키맵 파일(TOML) 텍스트 그대로. 형식 검사는 키맵 엔진(packages/keymap)이 한다. */
	content: string,
};

export type KeymapGetParams = {
	id: string,
};

export type KeymapInfo = {
	id: string,
	/**  기여한 확장의 id. */
	extension: string,
	kind: KeymapContributionKind,
};

export type KeymapList = {
	keymaps: KeymapInfo[],
};

export type LangDetectFile = {
	/**  절대 경로. 파일이 없어도 된다(저장하지 않은 새 파일). */
	path: string,
	/**
	 *  파일 앞부분(앞 50 KiB 까지만 본다 — 넘는 부분은 버린다). 없으면 빈 파일로 본다: 내용을 보는 단계(모드라인 · shebang ·
	 *  XML 머리 · 생성 파일의 앞 줄 규칙)는 맞지 않고, heuristics 는 확장자마다의 기본 규칙(`.md` → Markdown 등)이 고른다.
	 */
	head?: string | null,
};

export type LangDetectParams = {
	/**
	 *  있으면 그 프로젝트의 설정 매핑과 `.gitattributes` 를 본다. 없으면 전역 매핑과 Linguist 규칙만 본다(경로 규칙은 파일
	 *  이름에만 맞춘다).
	 */
	projectId?: string | null,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). 프로젝트 루트가 그 워크트리 안의 것이 된다. */
	worktree?: string | null,
	/**  최대 [`MAX_FILES`] 개. 결과는 같은 순서다. */
	files: LangDetectFile[],
};

export type LangDetectResult = {
	files: LangDetection[],
};

export type LangDetection = {
	/**  Linguist 언어 이름. `null` 이면 플레인 텍스트. */
	language: string | null,
	source: LangSource,
	/**  벤더 파일(vendor.yml 또는 `linguist-vendored`). */
	vendored: boolean,
	/**  생성 파일(`pw_lang::generated` 의 규칙 또는 `linguist-generated`). */
	generated: boolean,
	/**  문서 파일(documentation.yml 또는 `linguist-documentation`). */
	documentation: boolean,
};

export type LangInfo = {
	/**  Linguist 언어 이름(확장만 기여한 언어는 그 `linguist` 이름). `lang.detect` 의 `language` 와 같은 값이다. */
	name: string,
	/**  Linguist popular.yml 에 있다(고르기 팝업이 앞에 둔다). */
	popular: boolean,
	/**  줄 주석 기호(확장의 `[contributes.languages.<id>] line_comment`). 기여한 확장이 없거나 적지 않았으면 없다. */
	lineComment: string | null,
};

export type LangList = {
	/**  Linguist 표의 순서(이름순), 그 뒤에 Linguist 에 없는 확장 기여 언어가 등록 순서로. */
	languages: LangInfo[],
};

/**  언어를 정한 단계. */
export type LangSource = 
/**  설정의 `[languages.mapping]`. */
"mapping" | 
/**  `.gitattributes` 의 `linguist-language`. */
"gitattributes" | "modeline" | "filename" | "shebang" | "extension" | 
/**  앞 두 줄의 `xml version=`. */
"xml" | "manpage" | "heuristics" | 
/**
 *  Linguist 단계가 후보를 여럿 남겼다(Linguist 는 여기서 분류기를 쓴다 — 옮기지 않았다). 대표 확장자 · popular.yml 로
 *  고른다(`linguist::pick`).
 */
"ambiguous" | 
/**  확장의 `[contributes.languages]` 확장자. */
"contributed" | 
/**  정하지 못했다(플레인 텍스트). */
"none";

export type LanguageInfo = {
	/**  BCP 47 언어 태그. */
	locale: string,
	/**  그 언어로 쓴 그 언어의 이름(`language-name` 메시지, 없으면 태그). */
	name: string,
	/**  기여한 확장의 id. */
	extension: string,
};

/**  실행하지 못한 이유. 화면은 `kind` 로 번역된 문장을 고른다. */
export type LaunchProblem = 
/**  이 OS 의 목록에 없는 도구 id. */
{ kind: "unknownTool" } | 
/**  설정 형식 오류(`ExternalToolInfo.problem`). */
{ kind: "invalidTool"; message: string } | 
/**  명령이 쓰는 변수에 이 문맥의 값이 없다(중괄호 없는 이름, 예: `branch`). */
{ kind: "missingVariable"; variable: string } | 
/**  프로젝트 루트(작업 디렉터리)가 없다. */
{ kind: "projectRootMissing"; path: string } | 
/**  실행 파일을 찾지 못했다. `loginShellPath` 는 찾아본 PATH 가 로그인 셸의 것인가(아니면 앱 프로세스의 것). */
{ kind: "notFound"; program: string; loginShellPath: boolean } | 
/**  실행 파일을 띄우지 못했다(권한 등). */
{ kind: "spawnFailed"; program: string; message: string } | 
/**  `open`(macOS LaunchServices)에 번들 폴더(`*.app` 등)를 넘기려 했다 — `open` 은 번들을 열지 않고 실행하므로 띄우지 않았다. */
{ kind: "bundlePath"; path: string } | 
/**  띄운 런처가 곧바로 0 이 아닌 코드로 끝났다. 신호로 끝났으면 `code` 가 없다. */
{ kind: "exited"; code: number | null };

export type LayerOrigin = "builtin" | 
/**  `<id>.toml` — 커밋되는 공유 설정(전역이면 그냥 설정 파일). */
"shared" | 
/**  `<id>.local.toml` — 개인 덮어쓰기. 워크트리면 메인 체크아웃의 것일 수 있다. */
"local";

/**  읽은 범위의 줄바꿈. */
export type LineEnding = "lf" | "crlf" | "cr" | 
/**  둘 이상이 섞였다. */
"mixed" | 
/**  줄바꿈이 없다(한 줄). */
"none";

/**  응답 형태. `unary` 는 결과 하나, `stream` 은 `streamId` 를 돌려주고 청크를 `stream.chunk` 로 보낸다. */
export type MethodKind = "unary" | "stream";

/**  메서드 하나의 메타데이터. `rpc_method!` 가 상수로 만든다. */
export type MethodMeta = {
	/**  `<module>.<action>` (`docs/design/03-architecture.md` §4). */
	name: string,
	kind: MethodKind,
	tier: Tier,
	roles: Role[],
	/**  입력 타입의 소스 표기(`stringify!`). 표시용이다 — 타입 생성은 [`MethodInfo`](crate::MethodInfo) 의 실제 타입으로 한다. */
	params: string,
	/**  unary 는 결과 타입, stream 은 청크 항목 타입의 소스 표기. */
	output: string,
	/**  선언의 문서 주석. MCP 툴 설명의 원천. */
	doc: string,
	/**
	 *  MCP 툴로 내보내는가. 선언에서 `mcp: true` 로 고른 메서드만 툴이 된다 — 새 메서드는 말없이 툴이 되지 않는다.
	 *  툴 이름 · 노출 설정 · 등급 정책은 `crates/pw-mcp` 가 정한다(`docs/design/05-mcp.md` 「툴 레지스트리」 절).
	 */
	mcp: boolean,
	/**
	 *  파일 범위 호출자([`Caller::file`](crate::Caller::file), 단일 파일 창)도 부를 수 있는가. 선언에서 `file_scope: true` 로
	 *  고른 메서드만 — 그 핸들러는 [`Ctx::file_scope`](crate::Ctx::file_scope) 를 보고 그 파일 하나 밖에 닿지 않는다. 경로를
	 *  받지 않는 메서드(앱 정보 · 문자열)도 고른 것만 열린다. 새 메서드는 말없이 열리지 않는다.
	 */
	fileScope: boolean,
};

/**  서버 → 클라이언트 알림의 와이어 형식. [`Notification`] 이 이 형태로 직렬화된다. */
export type NotificationMessage = {
	jsonrpc: JsonRpcVersion,
	method: string,
	params: JsonValue,
};

export type OpenWithList = {
	/**  이 OS 에서 쓸 수 있는 도구(`platforms` 로 거른 것). 확장 순서, 그 뒤에 설정에서만 정의한 도구. */
	tools: ExternalToolInfo[],
	default: DefaultToolInfo,
};

export type OpenWithListParams = {
	/**  있으면 그 프로젝트의 설정(`[open_with] default`)까지 보고 기본 도구를 고른다. */
	projectId?: string | null,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). 그 워크트리의 `.local.toml` 을 읽는다. */
	worktree?: string | null,
};

export type OpenWithOutcome = { kind: "launched"; tool: string; label: string; 
/**  띄운 argv(첫 요소는 찾은 실행 파일의 절대 경로). */
argv: string[]; pid: number } | { kind: "failed"; tool: string; 
/**  목록에 없는 도구면 id. */
label: string; 
/**  치환까지 마친 argv. 치환 전에 실패했으면 비어 있다. */
argv: string[]; problem: LaunchProblem } | 
/**  도구를 고르지 않았고 기본 도구도 없다. `configured` 는 설정이 고른, 이 OS 에 없는 도구. */
{ kind: "noDefault"; configured: string | null };

export type OpenWithRunParams = {
	projectId: string,
	/**  없으면 기본 도구. 기본 도구가 없으면 `noDefault` 로 끝난다(창은 「다음에서 열기」 팝업을 연다). */
	tool?: string | null,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). `{project_root}` 와 작업 디렉터리가 그 워크트리 안의 프로젝트 루트가 된다. */
	worktree?: string | null,
	/**  열 파일의 절대 경로. 있으면 도구의 `file_command` 를 쓴다(없으면 `command`). */
	file?: string | null,
	line?: number | null,
	column?: number | null,
};

export type PathParams = {
	/**  절대 경로. 파일이든 폴더든, 없는 경로든 된다. */
	path: string,
};

export type PingParams = {
	/**  그대로 돌려받는 값. 클라이언트가 응답을 자기 요청과 맞춰 보는 데 쓴다. */
	nonce?: string,
};

export type Pong = {
	nonce: string,
	hostId: string,
};

/**  등록된 프로젝트. 경로는 [`path::normalize`] 로 정규화된 절대 경로다. */
export type Project = {
	/**  `$DATA/projects/<id>/` 에도 쓰이는 id(16자리 16진수). */
	id: string,
	name: string,
	/**  프로젝트가 있는 Host. 지금은 언제나 `local`. */
	host: string,
	/**  첫 번째가 주 루트다. 지금은 하나뿐이고, 여럿은 멀티 루트(F1-6)가 연다. */
	roots: string[],
	favorite: boolean,
	/**  정렬 · 중복 제거된 태그. */
	tags: string[],
	configMode: ConfigMode,
	/**  개인 전용 설정 폴더 이름. 만들 때 정하고 바뀌지 않는다([`slug`]). */
	slug: string,
	/**  만든 시각(유닉스 밀리초). */
	createdAt: number,
	/**  마지막으로 연 시각(유닉스 밀리초). 한 번도 안 열었으면 `null`. */
	openedAt: number | null,
};

export type ProjectIdParams = {
	id: string,
};

export type ProjectInfo = {
	project: Project,
	/**  주 루트 폴더가 디스크에 있는가. 없으면(옮기거나 지운 폴더) 아래 목록은 비어 있다. */
	rootExists: boolean,
	/**  주 루트에 있는 빌드 파일 이름(루트 후보와 같은 목록 · 순서). */
	buildFiles: string[],
	/**  빌드 파일에서 짐작한 언어(`rust`, `typescript` …). 먼저 나온 빌드 파일 순. */
	languages: string[],
	config: ConfigSummary,
};

/**  고칠 것만 채운다. */
export type ProjectPatch = {
	name?: string | null,
	favorite?: boolean | null,
	/**  통째로 바꾼다. */
	tags?: string[] | null,
	configMode?: ConfigMode | null,
};

/**  기능 메서드의 프로젝트 지정(`docs/design/03-architecture.md` §4). MCP 서버는 세션의 프로젝트가 있으면 이 키를 채워 준다. */
export type ProjectScopedParams = {
	/**  프로젝트 id(`project_list` 의 `id`). */
	projectId: string,
};

export type ProjectState = {
	/**  저장된 상태. 없거나 읽지 못했으면 `null`. */
	state: JsonValue | null,
	/**  파일이 있는데 읽지 못한 이유. 창은 로그에 남기고 기본 레이아웃으로 연다. */
	problem: string | null,
};

export type ProjectTrust = {
	projectId: string,
	/**  신뢰를 가진 프로젝트. 메인 저장소 프로젝트가 등록된 워크트리 프로젝트면 그 프로젝트, 아니면 `project_id` 와 같다. */
	ownerId: string,
	state: TrustState,
};

export type RecentParams = {
	/**  없으면 20. */
	limit?: number | null,
};

/**
 *  클라이언트 → 서버 요청 · 알림의 와이어 형식. `id` 가 없으면 알림이다.
 * 
 *  서버는 이 타입으로 역직렬화하지 않는다 — 오류마다 다른 응답을 내려고 손으로 검증한다(`parse`).
 *  이 타입은 형식의 선언이고 클라이언트(TS 생성 · 골든 메시지)가 쓴다. 둘이 맞는지는 이 파일의 테스트가 본다.
 * 
 *  없는 `id` · `params` 는 키를 생략한다 — `"id": null` 은 알림이 아니라 null id 요청이다.
 *  직렬화를 손으로 쓰는 이유는 [`RpcError`] 와 같다(`skip_serializing_if` 를 달면 specta 가 타입을 둘로 가른다).
 */
export type RequestMessage = {
	jsonrpc: JsonRpcVersion,
	id?: Id | null,
	method: string,
	params?: JsonValue,
};

/**  경로를 포함하는 프로젝트. */
export type Resolution = {
	project: Project,
	/**  경로를 포함한 등록 루트. */
	root: string,
	/**  정규화한 입력 경로. */
	path: string,
	/**  등록되지 않은 연결 워크트리를 거쳐 메인 저장소 프로젝트로 왔으면 그 워크트리(F2-5). 창은 이것을 활성 워크트리로 연다. */
	worktree: ActiveWorktree | null,
};

/**  서버 → 클라이언트 응답의 와이어 형식. [`Response`] 가 이 형태로 직렬화된다. */
export type ResponseMessage = ({ jsonrpc: JsonRpcVersion; id: Id; result: JsonValue }) & { error?: never } | ({ jsonrpc: JsonRpcVersion; id: Id; error: RpcError }) & { result?: never };

/**  호출자(페어링 기기)의 role. 값은 `docs/design/08-remote-mobile.md` 「보안 모델」 절을 따른다. */
export type Role = 
/**  Desktop. 전체. */
"owner" | 
/**  조회 + 메서드가 명시적으로 허용한 조작. */
"mobile" | 
/**  조회만. */
"readonly";

/**  루트 후보 하나. 순서와 이유의 규칙은 [`candidates`]. */
export type RootCandidate = {
	path: string,
	/**  연결 워크트리의 메인 체크아웃 꼭대기. */
	worktreeMain: boolean,
	/**  가장 가까운 VCS 루트(`.git`). */
	vcs: boolean,
	/**  이 폴더에 있는 빌드 파일 이름. */
	buildFiles: string[],
};

/**  JSON-RPC 2.0 오류 객체. 와이어 형식 그대로 직렬화된다. `data` 가 없으면 키를 생략한다. */
export type RpcError = {
	code: number,
	message: string,
	data?: JsonValue,
};

export type RuntimeGetParams = {
	projectId: string,
	/**  절대 경로. 프로젝트 루트나 그 루트를 담은 연결 워크트리 안이어야 한다. 없으면 프로젝트의 주 루트. */
	dir?: string | null,
};

export type RuntimeInfo = {
	/**  고른 제공자: `"mise"` · `"shell"`(로그인 셸) · `"none"`(프로젝트 설정 `[runtime] provider = "none"` — 앱 프로세스의 환경). */
	provider: string,
	source: RuntimeSource,
	status: RuntimeStatus,
	/**  제공자가 고정한 도구와 버전. 로그인 셸은 비어 있다. */
	tools: RuntimeToolInfo[],
};

/**  물러난 까닭의 갈래(상태바 경고, 06-roadmap.md 「리스크」 표의 외부 런타임 도구 행). */
export type RuntimeProblem = 
/**  로그인 셸을 읽지 못해 앱 프로세스의 환경을 쓴다. */
"loginShell" | 
/**  프로젝트에 제공자의 설정 파일(`mise.toml` 등)이 있는데 그 도구가 로그인 셸 PATH 에 없다. */
"notInstalled" | 
/**  도구가 그 설정 파일을 신뢰하지 않는다(`mise trust` 가 필요하다). Pitwall 의 프로젝트 신뢰와 별개다. */
"notTrusted" | 
/**  도구가 실패했다(끝 코드 · 시간 초과 · 알 수 없는 출력). */
"failed";

export type RuntimeReloadParams = {
	/**  다시 읽기를 부른 프로젝트. 이 프로젝트에는 언제나 `runtime.changed` 가 나간다. */
	projectId: string,
};

/**  환경을 실제로 어디서 얻었는가. */
export type RuntimeSource = 
/**  로그인 셸. `shell` 은 셸 실행 파일의 경로. */
{ kind: "loginShell"; shell: string } | 
/**  앱 프로세스의 환경(로그인 셸을 읽지 못했다). */
{ kind: "process" } | 
/**  디렉터리의 설정 파일로 환경을 만드는 제공자(mise 등). `files` 는 그 파일들의 경로. */
{ kind: "configFiles"; files: string[] };

export type RuntimeStatus = { kind: "ok" } | 
/**
 *  제공자가 실패해 그 아래 환경(로그인 셸, 또는 앱 프로세스)으로 물러났다. 남기지 않으므로 다음 요청이 다시 시도한다 —
 *  로그인 셸의 시간 초과만 냉각 동안(30초) 다시 시도하지 않는다.
 */
{ kind: "fallback"; 
/**  실패한 층마다의 이유(사람이 읽는 글, 원문). 여럿이면 `; ` 로 잇는다. */
reason: string; 
/**  무엇이 실패했는가. 제공자와 로그인 셸이 함께 실패했으면 제공자의 것이다(상태바 경고가 고르는 글). */
problem: RuntimeProblem };

export type RuntimeToolInfo = {
	name: string,
	version: string,
	/**  버전을 정한 파일. */
	sourceFile: string | null,
};

/**  파일 하나의 결과. */
export type SearchFile = {
	/**  걸어 간 경로(절대 경로). 루트 안 심링크를 지났으면 링크 쪽 경로다 — 실제 경로는 `fs.stat` 이 준다. */
	path: string,
	/**  줄 번호순. */
	lines: SearchLine[],
};

export type SearchFiles = {
	/**  점수순(같으면 짧은 경로 · 경로순). */
	files: FileMatch[],
	/**  맞은 파일 수(`files` 는 그 앞부분). */
	matched: number,
	/**  찾아본 파일 수(목록의 크기). */
	indexed: number,
};

export type SearchFilesParams = {
	projectId: string,
	/**
	 *  창의 활성 워크트리 꼭대기(`ActiveWorktree.top`). 있으면 그 워크트리 안의 프로젝트 루트를, 없으면 프로젝트의 등록 루트를
	 *  찾는다(`fs.watch` 와 같다).
	 */
	worktree?: string | null,
	/**
	 *  찾을 것. 공백으로 가른 낱말이 모두 맞아야 한다(낱말마다 퍼지, 대소문자는 대문자가 있을 때만 가린다). 비어 있으면 경로순
	 *  앞에서부터. 글자 수 상한 [`MAX_QUERY_CHARS`].
	 */
	query: string,
	/**  결과 수. 기본 [`DEFAULT_LIMIT`], 1 ~ [`MAX_LIMIT`]. */
	limit?: number | null,
};

/**  일치한 줄 하나. */
export type SearchLine = {
	/**  1 부터. */
	line: number,
	/**  줄의 일부(줄바꿈 제외). 줄이 [`PREVIEW_MAX`] 보다 길면 첫 일치 앞 [`PREVIEW_BEFORE`] 부터 잘라 낸다. */
	preview: string,
	/**  `preview` 가 줄의 어디서 시작하는가(UTF-16 코드 단위). 미리보기 안의 범위는 `range.start - previewStart` 다. */
	previewStart: number,
	/**  일치 범위(줄 기준, 앞에서부터). 미리보기에 걸친 것만 싣는다 — 첫 일치는 늘 든다. 그래서 많아야 [`PREVIEW_MAX`] + 1 개다. */
	ranges: SearchRange[],
	/**  미리보기 뒤에 이 줄의 일치가 더 있다(`ranges` 에 싣지 않은 「더 있음」). */
	more: boolean,
};

/**
 *  일치 범위. 줄 안의 UTF-16 코드 단위 위치(JS 문자열 · CodeMirror 의 위치 단위)이고 `end` 는 들지 않는다. UTF-8 이 아닌
 *  바이트는 대체 문자 하나로 센다.
 */
export type SearchRange = {
	start: number,
	end: number,
};

/**  `search.text` 의 청크. */
export type SearchTextChunk = 
/**  결과가 있는 파일들. 한 파일은 한 청크 안에만 있다. */
{ kind: "files"; files: SearchFile[] } | 
/**  마지막 청크. 상한 · 취소 없이 끝까지 찾았으면 `truncated` 가 꺼져 있다. */
{ kind: "done"; 
/**  결과가 있는 파일 수. */
matchedFiles: number; 
/**  보낸 결과(일치한 줄) 수. */
lines: number; 
/**  상한을 넘는 결과가 더 있다(「더 있음」). */
truncated: boolean; 
/**  내용을 찾아본 파일 수. */
searchedFiles: number; 
/**  바이너리라 건너뛴 파일 수. */
binaryFiles: number; 
/**  50 MiB 를 넘어 건너뛴 파일 수. */
largeFiles: number };

export type SearchTextParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). */
	worktree?: string | null,
	/**  찾을 폴더 · 파일(절대 경로, 하나 이상). 프로젝트 전체는 프로젝트 루트를 넘긴다. 루트 밖이면 invalid params. */
	paths: string[],
	/**  찾을 것. 비어 있으면 invalid params. */
	query: string,
	/**  `query` 가 정규식(Rust `regex` 문법)이다. 끄면 글자 그대로 찾는다. */
	regex?: boolean,
	/**  대소문자를 가린다. 끄면 가리지 않는다(유니코드 대소문자 접기). */
	matchCase?: boolean,
	/**  단어 단위로만 맞춘다(`rg -w`: 앞뒤가 단어 글자가 아니어야 한다). */
	wholeWord?: boolean,
	/**
	 *  이 글롭에 맞는 파일만 찾는다(`.gitignore` 문법, `rg -g`). `/` 가 없으면 어느 깊이의 이름에든, 있으면 찾는 폴더 기준 경로에
	 *  맞춘다. 비어 있으면 모든 파일.
	 */
	include?: string[],
	/**  이 글롭에 맞는 파일 · 폴더는 찾지 않는다(`rg -g '!글롭'`). `include` 보다 우선한다. */
	exclude?: string[],
	/**
	 *  `.gitignore` · `.git/info/exclude` · 전역 gitignore · `.ignore` 로 무시되는 파일을 건너뛴다(기본 켬). `.gitignore` 는
	 *  저장소(`.git`) 안에서만 적용된다(ripgrep 과 같다). 찾는 경로 위의 파일은 저장소 꼭대기까지만 본다(`pw_fs::search` 머리 주석).
	 */
	respectIgnore?: boolean,
	/**  벤더 파일(`vendor.yml` 의 경로 · `linguist-vendored`)을 건너뛴다. */
	excludeVendored?: boolean,
	/**  생성 파일(generated 의 경로 규칙 · `linguist-generated`)을 건너뛴다. */
	excludeGenerated?: boolean,
	/**  숨김 파일 · 폴더(`.` 으로 시작)도 찾는다. 켜도 `.git` 안은 찾지 않는다(링크로 들어가도). */
	hidden?: boolean,
	/**  결과(일치한 줄) 상한. 기본 [`DEFAULT_MAX_RESULTS`], 1 ~ [`MAX_RESULTS_LIMIT`]. */
	maxResults?: number | null,
};

